=== Method: calc (AbstractMethod) ===
/* The purpose of this class is to realize a torque balanced drive off, which has the 
   characteristic to release the brake force with the same gradient, like the propulsive force
   is increasing*/

// Get value for volume flow (NVH) limitation
if(FS_CSM_HoldConsiderNPumo)
{
	CSM_nPumo2q.calc(C_CSM_BrakeNPumoRef);
	q_MaxBrkIncRefBrake = CSM_nPumo2q.qBrake();
	CSM_nPumo2q.calc(C_CSM_DriveOffTrqBalNPumoMaxComfort);
	q_BrkIncComfort = CSM_nPumo2q.qBrake();
}
else
{
	q_MaxBrkIncRefBrake = C_CSM_BrakeQMaxBrkIncRef;
	q_BrkIncComfort = C_CSM_DriveOffTrqBalQMaxComfort;
}

CSM_PT1_AActProp.calc(AActProp,CycleTime,C_CSM_DriveOffAActPropTimeConstantTrqBal,true);
AActProp_filt = CSM_PT1_AActProp.filtered_value();

// Get gradient of propulsive force
AActPropDelta = (AActProp_filt - AActPropfiltK1);
JActProp = AActPropDelta/CycleTime;

// Define the final torque balance mode
if(CsmDrvOffTrqBalWithBrkInc == CSMDrvOffTrqBalModeWithBrkInc_Off)
{
	if(CsmDrvOffTrqBalWoBrkInc == CSMDrvOffTrqBalModeWoBrkInc_LessSensitive)
	{
		CsmHoldDrvOffTrqBalMode = CSMDrvOffTrqBalMode_LessSensitiveWoBrkInc;
	}
	else if(CsmDrvOffTrqBalWoBrkInc == CSMDrvOffTrqBalModeWoBrkInc_Sensitive)
	{
		CsmHoldDrvOffTrqBalMode = CSMDrvOffTrqBalMode_SensitiveWoBrkInc;
	}
	else
	{
		CsmHoldDrvOffTrqBalMode = CSMDrvOffTrqBalMode_Off;
	}
}else if(CsmDrvOffTrqBalWithBrkInc == CSMDrvOffTrqBalModeWithBrkInc_LessSensitive)
{
	CsmHoldDrvOffTrqBalMode = CSMDrvOffTrqBalMode_LessSensitiveWithBrkInc;
}else //if(CsmDrvOffTrqBalWithBrkInc == CSMDrvOffTrqBalModeWithBrkInc_Sensitive)
{
	if(CsmDrvOffTrqBalWoBrkInc == CSMDrvOffTrqBalModeWoBrkInc_LessSensitive)
	{
		CsmHoldDrvOffTrqBalMode = CSMDrvOffTrqBalMode_LessSensitiveWithBrkInc;
	}else if(CsmDrvOffTrqBalWoBrkInc == CSMDrvOffTrqBalModeWoBrkInc_Sensitive)
	{
		CsmHoldDrvOffTrqBalMode = CSMDrvOffTrqBalMode_SensitiveWithBrkInc;
	}else
	{
		CsmHoldDrvOffTrqBalMode = CSMDrvOffTrqBalMode_SensitiveWithBrkInc;
	}
}

// Freeze Slope for more robust drive off
if(	   (	VehStop      == true
		&&	CsmHoldState == CSMHoldState_BrkInc)
	|| (	CsmHoldComfortReleaseActive == true
		&&	VehStop                     == true
		&&	CsmHoldState                == CSMHoldState_DriveOff)
	|| CsmHoldState == CSMHoldState_NotActive
	|| CsmHoldState == CSMHoldState_RollPrev
	|| CsmHoldState == CSMHoldState_BrkHold)
{
	// In case neutral gear is selected a release should be considered, like downhill
	// because the vehicle will move downhill
	if(VehMovDirGear == CSMVehMovDir_Undefined)
	{
		ASlopeFreezed = -(ASlopeGear.abs());
	}else
	{
		ASlopeFreezed = ASlopeGear;
	}
}

// Determine whether drive off should be already finished
if(VVehComfort > C_CSM_DriveOffTrqBalVehMovVThresholdWithNoWssDir)
{
	TimeVehMov = (TimeVehMov + CycleTime).min(11); //11 because the max implemetation of the parameter C_CSM_DriveOffTrqBalVehMovTimeThresholdWithNoWssDir is 10
}else
{
	TimeVehMov = 0;
}

if(WssDirValid)
{
	if(		(VehMovDirWss == CSMVehMovDir_Forward && VehMovDirGear == CSMVehMovDir_Forward)
		||	(VehMovDirWss == CSMVehMovDir_Backward && VehMovDirGear == CSMVehMovDir_Backward))
	{
		DriveOffFinished = true;
	}else
	{
		DriveOffFinished = false;
	}
	 
}else
{
	if(TimeVehMov >= C_CSM_DriveOffTrqBalVehMovTimeThresholdWithNoWssDir.getAt(VVehComfort))
	{
		DriveOffFinished = true;
	}else
	{
		DriveOffFinished = false;
	}
}

// Drive Off
CsmDriveOffTimeConstantToEq = C_CSM_DriveOffTimeConstantToEq.getAt(AActProp,ASlopeFreezed);


// Determine equilibrium value
ABrakeEqPreview = (-(ASlopeFreezed - (AActProp+JActProp*((CsmDriveOffTimeConstantToEq-TimeSinceRelease).max(0)))));
ABrakeEqPreview = ((ABrakeEqPreview * C_CSM_DriveOffABrakeEqSensFac.getAt(ASlopeFreezed))- C_CSM_DriveOffTrqBalanceAOffset).min(0);

ABrakeEq = (-(ASlopeFreezed - (AActProp)));
ABrakeEq = ((ABrakeEq * C_CSM_DriveOffABrakeEqSensFac.getAt(ASlopeFreezed))- C_CSM_DriveOffTrqBalanceAOffset).min(0);


// if Drive Off triggered consider release ramp calculations
if(CsmHoldDriveReqActive > 0)
{
	if(EqReached == false)
	{
		CsmjDriveOff = ((CsmHoldATarBrk.abs()- ABrakeEqPreview.abs()) / ((CsmDriveOffTimeConstantToEq - TimeSinceRelease).max(CycleTime)));
	}
	else
	{
		CsmjDriveOff = ((CsmHoldATarBrk.abs()- ABrakeEq.abs()) / CycleTime);
	}
	
	ABrakeDeltaIntegral = CsmjDriveOff * CycleTime;
	
	if(CsmjDriveOff > 0)
	{
		EqReached = EqReached;

		if(C_CSM_DriveOffTrqBalABrakeDelta4DecMin > ABrakeDeltaIntegral
			&& CsmHoldATarBrk + ABrakeDeltaIntegral < 0
			&& EqReached == true)
		{
			CsmjDriveOff = 0;
		}else
		{
			CsmjDriveOff = CsmjDriveOff.min(C_CSM_DriveOffjMax);
		}
	}
	else
	{
		EqReached = true;
		if(CsmjDriveOff == 0)
		{
			CsmjDriveOff = 0;
		}else if(	CsmHoldDrvOffTrqBalMode == CSMDrvOffTrqBalMode_LessSensitiveWithBrkInc
				||	CsmHoldDrvOffTrqBalMode == CSMDrvOffTrqBalMode_SensitiveWithBrkInc)
		{
			if(C_CSM_DriveOffTrqBalABrakeDelta4IncMin < ABrakeDeltaIntegral)
			{
				CsmjDriveOff = 0;
			}else
			{
				CsmjBrkIncLimited = JMinRef * q_BrkIncComfort/q_MaxBrkIncRefBrake;
				temp_CsmjBrkInc = (C_CSM_DriveOffjMaxInc).max(CsmjBrkIncLimited);
				
				CsmjDriveOff = CsmjDriveOff.max(temp_CsmjBrkInc);
			}
		}else
		{
			CsmjDriveOff = 0;
		}
	}
	// upper limit of drive off request to secure hw limit for case of trq bal with brk inc
	CsmHoldDriveOffATarBrk = ((CsmHoldATarBrk + CsmjDriveOff * CycleTime).min(0)).max(CsmHoldATarThermLimit);
	
	TimeSinceRelease = TimeSinceRelease + CycleTime;
	
	
	if(
			(	CsmHoldDrvOffTrqBalActive == false
			||	DriveOffFinished == false)
		&&
			(	CsmHoldDrvOffTrqBalMode == CSMDrvOffTrqBalMode_SensitiveWoBrkInc
			||	CsmHoldDrvOffTrqBalMode == CSMDrvOffTrqBalMode_SensitiveWithBrkInc
			||	CsmHoldDrvOffTrqBalMode == CSMDrvOffTrqBalMode_LessSensitiveWithBrkInc
			||	CsmHoldDrvOffTrqBalMode == CSMDrvOffTrqBalMode_LessSensitiveWoBrkInc)
		&&	CsmDrvOffTrqBalance == true
		&&	(CsmHoldBrkHoldActive == true
			||	CsmHoldDrvOffTrqBalActive == true)
		&&	(	CsmHoldATarBrk < 0
			||	(	CsmHoldDrvOffTrqBalActive
				&&	(	CsmHoldDrvOffTrqBalMode == CSMDrvOffTrqBalMode_SensitiveWithBrkInc
					||	CsmHoldDrvOffTrqBalMode == CSMDrvOffTrqBalMode_LessSensitiveWithBrkInc)))
		&&	(	CsmHoldDrvOffTrqBalMode == CSMDrvOffTrqBalMode_SensitiveWoBrkInc
			||	CsmHoldDrvOffTrqBalMode == CSMDrvOffTrqBalMode_SensitiveWithBrkInc
			||	(	CsmHoldDrvOffTrqBalMode == CSMDrvOffTrqBalMode_LessSensitiveWithBrkInc
				&&	(ABrakeEq.max(ABrakeEqPreview)) >= (C_CSM_DriveOffTrqBalABrakeEqThresholdRobustness.getAt(ASlopeFreezed)).min(C_CSM_DriveOffTrqBalanceAOffset))
			||	(	CsmHoldDrvOffTrqBalMode == CSMDrvOffTrqBalMode_LessSensitiveWoBrkInc
				&&	(ABrakeEq.max(ABrakeEqPreview)) >= (C_CSM_DriveOffTrqBalABrakeEqThresholdRobustness.getAt(ASlopeFreezed)).min(C_CSM_DriveOffTrqBalanceAOffset))
			||	CsmHoldDrvOffTrqBalActive == true))
	{
		CsmHoldDrvOffTrqBalActive = true;
		if(		CsmHoldATarBrk > ABrakeEq
			&&	CsmHoldDriveOffATarBrk > ABrakeEq
			&&	CsmHoldDriveOffATarBrk > CsmHoldATarThermLimit) // only enable increase as long as thermal limit is not reached yet
		{
			CsmHoldDrvOffTrqBalEnableReactByBrkInc = true;
		}else
		{
			CsmHoldDrvOffTrqBalEnableReactByBrkInc = false;
		}
		
		EqReached = EqReached;
	}else
	{
		CsmHoldDrvOffTrqBalActive = false;
		CsmHoldDrvOffTrqBalEnableReactByBrkInc = true;
		TimeSinceRelease = 0;
		EqReached = false;
	}
	
}else
{
	CsmjDriveOff = 15000;
	CsmHoldDrvOffTrqBalActive = false;
	CsmHoldDrvOffTrqBalEnableReactByBrkInc = true;
	
	TimeSinceRelease = 0;
	EqReached = false;
	
	CsmHoldDriveOffATarBrk = 0;
}


AActPropfiltK1 = AActProp_filt;


=== Method: CsmHoldDriveOffATarBrk (AbstractMethod) ===
return CsmHoldDriveOffATarBrk;


=== Method: CsmHoldDrvOffTrqBalActive (AbstractMethod) ===
return CsmHoldDrvOffTrqBalActive;


=== Method: CsmHoldDrvOffTrqBalEnableReactByBrkInc (AbstractMethod) ===
return CsmHoldDrvOffTrqBalEnableReactByBrkInc;


=== Method: CsmHoldDrvOffTrqBalMode (AbstractMethod) ===
return CsmHoldDrvOffTrqBalMode;
